 function chart(view,series,{min=-85,max=40,xLabel='Условное время',yLabel='Vm, мВ',threshold=null}={}){const s=diagram(view,'График: '+yLabel+'; '+xLabel);function draw(lines){s.replaceChildren();const xx=(v,end)=>55+v/end*555,yy=v=>235-(v-min)/(max-min)*195;line(s,55,40,55,235,'#6a746d',1);line(s,55,235,610,235,'#6a746d',1);[min,Math.round((min+max)/2),max].forEach(v=>{label(s,5,yy(v)+5,String(v));});label(s,58,24,yLabel);label(s,290,278,xLabel);if(threshold!==null){const l=svg('line',{x1:55,x2:610,y1:yy(threshold),y2:yy(threshold),stroke:'#be8051','stroke-dasharray':'5 5'});s.append(l);label(s,480,yy(threshold)-8,'Порог');}for(const [i,points]of lines.entries()){const end=points[points.length-1]?.[0]||1;s.append(svg('polyline',{points:points.map(([x,y])=>xx(x,end)+','+yy(y)).join(' '),fill:'none',stroke:i?'#be8051':'#285545','stroke-width':3}));}}draw(series);return{svg:s,draw,setLabels(x,y){xLabel=x;yLabel=y;}};}
